    op.execute("CREATE OR REPLACE FUNCTION public.mindatlas_ai_model_capability_probe_immutable()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\n        BEGIN\n            RAISE EXCEPTION\n                'MINDATLAS_PLAN03_PROBE: ai_model_capability_probe rows are immutable'\n                USING ERRCODE = 'integrity_constraint_violation';\n        END;\n        $function$")
    op.execute("CREATE OR REPLACE FUNCTION public.mindatlas_ai_model_probe_pointer_guard()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\n        DECLARE\n            owner_model_id uuid;\n        BEGIN\n            IF NEW.current_capability_probe_id IS NULL THEN\n                RETURN NEW;\n            END IF;\n            SELECT model_id INTO owner_model_id\n            FROM ai_model_capability_probe\n            WHERE id = NEW.current_capability_probe_id;\n            IF owner_model_id IS NULL THEN\n                RAISE EXCEPTION\n                    'MINDATLAS_PLAN03_PROBE: current_capability_probe_id does not exist'\n                    USING ERRCODE = 'foreign_key_violation';\n            END IF;\n            IF owner_model_id IS DISTINCT FROM NEW.id THEN\n                RAISE EXCEPTION\n                    'MINDATLAS_PLAN03_PROBE: current_capability_probe_id must belong to the same model'\n                    USING ERRCODE = 'integrity_constraint_violation';\n            END IF;\n            RETURN NEW;\n        END;\n        $function$")
    op.execute("CREATE OR REPLACE FUNCTION public.mindatlas_assistant_run_interrupt_mutation()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\n        DECLARE\n            allow_purge text;\n            token_only boolean;\n            resolve_only boolean;\n        BEGIN\n            IF TG_OP = 'DELETE' THEN\n                allow_purge := current_setting('mindatlas.allow_durable_run_purge', true);\n                IF allow_purge IS DISTINCT FROM 'on' THEN\n                    RAISE EXCEPTION\n                        'MINDATLAS_PLAN07_IMMUTABLE_INTERRUPT: DELETE requires '\n                        'SET LOCAL mindatlas.allow_durable_run_purge = ''on'''\n                        USING ERRCODE = 'integrity_constraint_violation';\n                END IF;\n                RETURN OLD;\n            END IF;\n\n            -- Immutable request / suspension identity.\n            IF NEW.id IS DISTINCT FROM OLD.id\n               OR NEW.run_id IS DISTINCT FROM OLD.run_id\n               OR NEW.interrupt_key IS DISTINCT FROM OLD.interrupt_key\n               OR NEW.kind IS DISTINCT FROM OLD.kind\n               OR NEW.checkpoint_id IS DISTINCT FROM OLD.checkpoint_id\n               OR NEW.manifest_revision_id IS DISTINCT FROM OLD.manifest_revision_id\n               OR NEW.owner_skill_package_id IS DISTINCT FROM OLD.owner_skill_package_id\n               OR NEW.owner_skill_version_id IS DISTINCT FROM OLD.owner_skill_version_id\n               OR NEW.capability_call_id IS DISTINCT FROM OLD.capability_call_id\n               OR NEW.workflow_frame_id IS DISTINCT FROM OLD.workflow_frame_id\n               OR NEW.node_id IS DISTINCT FROM OLD.node_id\n               OR NEW.node_visit_id IS DISTINCT FROM OLD.node_visit_id\n               OR NEW.request_revision IS DISTINCT FROM OLD.request_revision\n               OR NEW.request_run_revision IS DISTINCT FROM OLD.request_run_revision\n               OR NEW.budget_revision_id IS DISTINCT FROM OLD.budget_revision_id\n               OR NEW.budget_suspension_state::jsonb IS DISTINCT FROM OLD.budget_suspension_state::jsonb\n               OR NEW.budget_suspension_digest IS DISTINCT FROM OLD.budget_suspension_digest\n               OR NEW.request_payload::jsonb IS DISTINCT FROM OLD.request_payload::jsonb\n               OR NEW.request_digest IS DISTINCT FROM OLD.request_digest\n               OR NEW.field_schema::jsonb IS DISTINCT FROM OLD.field_schema::jsonb\n               OR NEW.field_schema_digest IS DISTINCT FROM OLD.field_schema_digest\n               OR NEW.initial_values::jsonb IS DISTINCT FROM OLD.initial_values::jsonb\n               OR NEW.expires_at IS DISTINCT FROM OLD.expires_at\n               OR NEW.created_at IS DISTINCT FROM OLD.created_at\n            THEN\n                RAISE EXCEPTION\n                    'MINDATLAS_PLAN07_IMMUTABLE_INTERRUPT: request/suspension identity is immutable'\n                    USING ERRCODE = 'integrity_constraint_violation';\n            END IF;\n\n            -- Token rotation: pending stays pending; only token fields + updated_at change.\n            token_only := (\n                OLD.status = 'pending'\n                AND NEW.status = 'pending'\n                AND NEW.token_revision = OLD.token_revision + 1\n                AND NEW.resume_token_digest IS DISTINCT FROM OLD.resume_token_digest\n                AND NEW.resolution_checkpoint_id IS NOT DISTINCT FROM OLD.resolution_checkpoint_id\n                AND NEW.resolution_budget_revision_id IS NOT DISTINCT FROM OLD.resolution_budget_revision_id\n                AND NEW.resolution_run_revision IS NOT DISTINCT FROM OLD.resolution_run_revision\n                AND NEW.submitted_values::jsonb IS NOT DISTINCT FROM OLD.submitted_values::jsonb\n                AND NEW.decision IS NOT DISTINCT FROM OLD.decision\n                AND NEW.comment IS NOT DISTINCT FROM OLD.comment\n                AND NEW.resolution_request_id IS NOT DISTINCT FROM OLD.resolution_request_id\n                AND NEW.resolution_digest IS NOT DISTINCT FROM OLD.resolution_digest\n                AND NEW.resolved_at IS NOT DISTINCT FROM OLD.resolved_at\n            );\n            IF token_only THEN\n                RETURN NEW;\n            END IF;\n\n            -- One pending -> terminal resolution mutation.\n            resolve_only := (\n                OLD.status = 'pending'\n                AND NEW.status IN ('approved','rejected','submitted','cancelled','expired')\n                AND NEW.decision IS NOT NULL\n                AND NEW.resolved_at IS NOT NULL\n                AND NEW.resolution_request_id IS NOT NULL\n                AND NEW.resolution_digest IS NOT NULL\n                -- Token is consumed (cleared) or left null; revision must not decrease.\n                AND NEW.token_revision >= OLD.token_revision\n            );\n            IF resolve_only THEN\n                RETURN NEW;\n            END IF;\n\n            RAISE EXCEPTION\n                'MINDATLAS_PLAN07_IMMUTABLE_INTERRUPT: only token rotation or one pending->terminal resolution is allowed'\n                USING ERRCODE = 'integrity_constraint_violation';\n        END;\n        $function$")
    op.execute("CREATE OR REPLACE FUNCTION public.mindatlas_binding_closure_guard()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\n        DECLARE\n            rec record;\n            snap jsonb;\n            idx jsonb;\n            idx_count integer;\n            dep_count integer;\n            missing integer;\n            extra integer;\n        BEGIN\n            FOR rec IN\n                SELECT id, resolution_status, resolution_snapshot,\n                       dependency_closure_digest, binding_contract_digest,\n                       input_schema_digest, output_schema_digest,\n                       resolution_digest\n                  FROM assistant_skill_capability_binding\n                 WHERE resolution_status = 'resolved'\n            LOOP\n                -- Snapshot digest fields must equal row columns.\n                IF rec.resolution_snapshot IS NULL THEN\n                    RAISE EXCEPTION\n                        'MINDATLAS_PLAN01_CLOSURE: resolved binding missing snapshot'\n                        USING ERRCODE = 'integrity_constraint_violation';\n                END IF;\n\n                snap := rec.resolution_snapshot::jsonb;\n\n                -- Resolved bindings require digest keys to exist and equal columns\n                -- (not only when present). Input/output pairing stays required.\n                -- resolutionDigest may be top-level (legacy) or under target\n                -- (production build_binding_snapshot path).\n                IF (NOT (snap ? 'inputSchemaDigest'))\n                   OR (NOT (snap ? 'outputSchemaDigest'))\n                   OR (\n                        (NOT (snap ? 'resolutionDigest'))\n                        AND (snap #>> '{target,resolutionDigest}') IS NULL\n                      )\n                   OR (NOT (snap ? 'dependencyClosureDigest'))\n                   OR (NOT (snap ? 'bindingContractDigest'))\n                   OR (snap->>'inputSchemaDigest') IS DISTINCT FROM rec.input_schema_digest\n                   OR (snap->>'outputSchemaDigest') IS DISTINCT FROM rec.output_schema_digest\n                   OR COALESCE(\n                        snap->>'resolutionDigest',\n                        snap #>> '{target,resolutionDigest}'\n                      ) IS DISTINCT FROM rec.resolution_digest\n                   OR (snap->>'dependencyClosureDigest')\n                        IS DISTINCT FROM rec.dependency_closure_digest\n                   OR (snap->>'bindingContractDigest')\n                        IS DISTINCT FROM rec.binding_contract_digest\n                THEN\n                    RAISE EXCEPTION\n                        'MINDATLAS_PLAN01_CLOSURE: snapshot digests must equal binding columns'\n                        USING ERRCODE = 'integrity_constraint_violation';\n                END IF;\n\n                idx := COALESCE(\n                    snap->'dependencyClosure',\n                    snap->'dependency_closure',\n                    snap->'closureIndex',\n                    '[]'::jsonb\n                );\n                IF jsonb_typeof(idx) <> 'array' THEN\n                    RAISE EXCEPTION\n                        'MINDATLAS_PLAN01_CLOSURE: dependencyClosure must be an array'\n                        USING ERRCODE = 'integrity_constraint_violation';\n                END IF;\n\n                SELECT COUNT(*) INTO idx_count FROM jsonb_array_elements(idx);\n                SELECT COUNT(*) INTO dep_count\n                  FROM assistant_skill_capability_dependency d\n                 WHERE d.binding_id = rec.id;\n\n                IF idx_count <> dep_count THEN\n                    RAISE EXCEPTION\n                        'MINDATLAS_PLAN01_CLOSURE: dependency row count must match closure index'\n                        USING ERRCODE = 'integrity_constraint_violation';\n                END IF;\n\n                SELECT COUNT(*) INTO missing\n                  FROM jsonb_array_elements(idx) WITH ORDINALITY AS e(elem, ord)\n                 WHERE NOT EXISTS (\n                    SELECT 1\n                      FROM assistant_skill_capability_dependency d\n                     WHERE d.binding_id = rec.id\n                       AND d.ordinal = COALESCE(\n                            (e.elem->>'ordinal')::integer,\n                            (e.ord - 1)::integer\n                       )\n                       AND d.dependency_path = COALESCE(\n                            e.elem->>'path',\n                            e.elem->>'dependencyPath',\n                            e.elem->>'dependency_path'\n                       )\n                       AND d.dependency_digest = COALESCE(\n                            e.elem->>'dependencyDigest',\n                            e.elem->>'dependency_digest'\n                       )\n                 );\n                IF missing > 0 THEN\n                    RAISE EXCEPTION\n                        'MINDATLAS_PLAN01_CLOSURE: missing dependency row for closure index entry'\n                        USING ERRCODE = 'integrity_constraint_violation';\n                END IF;\n\n                SELECT COUNT(*) INTO extra\n                  FROM assistant_skill_capability_dependency d\n                 WHERE d.binding_id = rec.id\n                   AND NOT EXISTS (\n                    SELECT 1\n                      FROM jsonb_array_elements(idx) WITH ORDINALITY AS e(elem, ord)\n                     WHERE d.ordinal = COALESCE(\n                            (e.elem->>'ordinal')::integer,\n                            (e.ord - 1)::integer\n                       )\n                       AND d.dependency_path = COALESCE(\n                            e.elem->>'path',\n                            e.elem->>'dependencyPath',\n                            e.elem->>'dependency_path'\n                       )\n                       AND d.dependency_digest = COALESCE(\n                            e.elem->>'dependencyDigest',\n                            e.elem->>'dependency_digest'\n                       )\n                 );\n                IF extra > 0 THEN\n                    RAISE EXCEPTION\n                        'MINDATLAS_PLAN01_CLOSURE: extra dependency row not in closure index'\n                        USING ERRCODE = 'integrity_constraint_violation';\n                END IF;\n            END LOOP;\n            RETURN NULL;\n        END;\n        $function$")
    op.execute("CREATE OR REPLACE FUNCTION public.mindatlas_capability_call_attempt_append_only()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n    IF TG_OP = 'DELETE' THEN\n        RAISE EXCEPTION\n            'MINDATLAS_PLAN08_ATTEMPT_APPEND_ONLY: attempts cannot be deleted'\n            USING ERRCODE = 'integrity_constraint_violation';\n    END IF;\n\n    IF NEW.id IS DISTINCT FROM OLD.id\n       OR NEW.call_id IS DISTINCT FROM OLD.call_id\n       OR NEW.attempt_number IS DISTINCT FROM OLD.attempt_number\n       OR NEW.worker_id IS DISTINCT FROM OLD.worker_id\n       OR NEW.lease_generation IS DISTINCT FROM OLD.lease_generation\n       OR NEW.started_at IS DISTINCT FROM OLD.started_at\n       OR NEW.dispatch_deadline_at IS DISTINCT FROM OLD.dispatch_deadline_at\n       OR NEW.created_at IS DISTINCT FROM OLD.created_at\n    THEN\n        RAISE EXCEPTION\n            'MINDATLAS_PLAN08_ATTEMPT_IMMUTABLE: identity/counter fields are immutable'\n            USING ERRCODE = 'integrity_constraint_violation';\n    END IF;\n\n    IF (OLD.ended_at IS NOT NULL\n            AND NEW.ended_at IS DISTINCT FROM OLD.ended_at)\n       OR (OLD.external_request_id IS NOT NULL\n            AND NEW.external_request_id IS DISTINCT FROM OLD.external_request_id)\n       OR (OLD.external_idempotency_echo IS NOT NULL\n            AND NEW.external_idempotency_echo IS DISTINCT FROM OLD.external_idempotency_echo)\n       OR (OLD.request_digest IS NOT NULL\n            AND NEW.request_digest IS DISTINCT FROM OLD.request_digest)\n       OR (OLD.response_digest IS NOT NULL\n            AND NEW.response_digest IS DISTINCT FROM OLD.response_digest)\n       OR (OLD.transport_status IS NOT NULL\n            AND NEW.transport_status IS DISTINCT FROM OLD.transport_status)\n       OR (OLD.side_effect_started AND NOT NEW.side_effect_started)\n       OR (OLD.side_effect_started_at IS NOT NULL\n            AND NEW.side_effect_started_at IS DISTINCT FROM OLD.side_effect_started_at)\n       OR (OLD.error_code IS NOT NULL\n            AND NEW.error_code IS DISTINCT FROM OLD.error_code)\n       OR (OLD.retry_classification IS NOT NULL\n            AND NEW.retry_classification IS DISTINCT FROM OLD.retry_classification)\n       OR (OLD.diagnostic_artifact_id IS NOT NULL\n            AND NEW.diagnostic_artifact_id IS DISTINCT FROM OLD.diagnostic_artifact_id)\n    THEN\n        RAISE EXCEPTION\n            'MINDATLAS_PLAN08_ATTEMPT_IMMUTABLE: captured evidence is immutable once set'\n            USING ERRCODE = 'integrity_constraint_violation';\n    END IF;\n\n    IF NOT (\n        (OLD.status = 'claimed'\n            AND NEW.status IN ('dispatched','failed','abandoned'))\n        OR (OLD.status = 'dispatched'\n            AND NEW.status IN ('response_received','failed','uncertain'))\n        OR (OLD.status = 'response_received'\n            AND NEW.status IN ('committed','failed','uncertain'))\n    ) THEN\n        RAISE EXCEPTION\n            'MINDATLAS_PLAN08_ATTEMPT_TRANSITION: illegal attempt status transition % -> %',\n            OLD.status, NEW.status\n            USING ERRCODE = 'integrity_constraint_violation';\n    END IF;\n\n    IF NEW.status = 'dispatched'\n       AND (NEW.request_digest IS NULL OR NEW.response_digest IS NOT NULL)\n    THEN\n        RAISE EXCEPTION\n            'MINDATLAS_PLAN08_ATTEMPT_EVIDENCE: dispatched requires request evidence only'\n            USING ERRCODE = 'integrity_constraint_violation';\n    END IF;\n\n    IF NEW.status IN ('response_received','committed')\n       AND (NEW.request_digest IS NULL OR NEW.response_digest IS NULL)\n    THEN\n        RAISE EXCEPTION\n            'MINDATLAS_PLAN08_ATTEMPT_EVIDENCE: captured response requires request and response digests'\n            USING ERRCODE = 'integrity_constraint_violation';\n    END IF;\n\n    IF NEW.status IN ('committed','failed','uncertain','abandoned')\n       AND NEW.ended_at IS NULL\n    THEN\n        RAISE EXCEPTION\n            'MINDATLAS_PLAN08_ATTEMPT_EVIDENCE: terminal attempt requires ended_at'\n            USING ERRCODE = 'integrity_constraint_violation';\n    END IF;\n\n    IF NEW.status IN ('claimed','dispatched','response_received')\n       AND NEW.ended_at IS NOT NULL\n    THEN\n        RAISE EXCEPTION\n            'MINDATLAS_PLAN08_ATTEMPT_EVIDENCE: active attempt cannot have ended_at'\n            USING ERRCODE = 'integrity_constraint_violation';\n    END IF;\n\n    RETURN NEW;\nEND;\n$function$")
    op.execute("CREATE OR REPLACE FUNCTION public.mindatlas_capability_call_immutable_identity()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\n        BEGIN\n            IF TG_OP = 'DELETE' THEN\n                RAISE EXCEPTION\n                    'MINDATLAS_PLAN08_CALL_IMMUTABLE: capability call rows cannot be deleted'\n                    USING ERRCODE = 'integrity_constraint_violation';\n            END IF;\n\n            IF NEW.id IS DISTINCT FROM OLD.id\n               OR NEW.run_id IS DISTINCT FROM OLD.run_id\n               OR NEW.manifest_revision_id IS DISTINCT FROM OLD.manifest_revision_id\n               OR NEW.logical_call_key IS DISTINCT FROM OLD.logical_call_key\n               OR NEW.owner_kind IS DISTINCT FROM OLD.owner_kind\n               OR NEW.owner_id IS DISTINCT FROM OLD.owner_id\n               OR NEW.owner_version_id IS DISTINCT FROM OLD.owner_version_id\n               OR NEW.capability_type IS DISTINCT FROM OLD.capability_type\n               OR NEW.domain_key IS DISTINCT FROM OLD.domain_key\n               OR NEW.target_id IS DISTINCT FROM OLD.target_id\n               OR NEW.target_version_id IS DISTINCT FROM OLD.target_version_id\n               OR NEW.descriptor_digest IS DISTINCT FROM OLD.descriptor_digest\n               OR NEW.authorization_digest IS DISTINCT FROM OLD.authorization_digest\n               OR NEW.input_artifact_id IS DISTINCT FROM OLD.input_artifact_id\n               OR NEW.input_digest IS DISTINCT FROM OLD.input_digest\n               OR NEW.side_effect_class IS DISTINCT FROM OLD.side_effect_class\n               OR NEW.execution_mode IS DISTINCT FROM OLD.execution_mode\n               OR NEW.idempotency_key IS DISTINCT FROM OLD.idempotency_key\n               OR NEW.parent_call_id IS DISTINCT FROM OLD.parent_call_id\n               OR NEW.provider_tool_call_id IS DISTINCT FROM OLD.provider_tool_call_id\n               OR NEW.created_at IS DISTINCT FROM OLD.created_at\n            THEN\n                RAISE EXCEPTION\n                    'MINDATLAS_PLAN08_CALL_IMMUTABLE: identity/evidence fields are immutable'\n                    USING ERRCODE = 'integrity_constraint_violation';\n            END IF;\n\n            IF OLD.approval_binding_digest IS NOT NULL\n               AND NEW.approval_binding_digest IS DISTINCT FROM OLD.approval_binding_digest\n            THEN\n                RAISE EXCEPTION\n                    'MINDATLAS_PLAN08_CALL_IMMUTABLE: approval_binding_digest is immutable once set'\n                    USING ERRCODE = 'integrity_constraint_violation';\n            END IF;\n\n            IF OLD.side_effect_started_at IS NOT NULL\n               AND NEW.side_effect_started_at IS DISTINCT FROM OLD.side_effect_started_at\n            THEN\n                RAISE EXCEPTION\n                    'MINDATLAS_PLAN08_CALL_IMMUTABLE: side_effect_started_at is irreversible'\n                    USING ERRCODE = 'integrity_constraint_violation';\n            END IF;\n\n            IF NEW.state_revision < OLD.state_revision THEN\n                RAISE EXCEPTION\n                    'MINDATLAS_PLAN08_CALL_REVISION: state_revision must be monotonic'\n                    USING ERRCODE = 'integrity_constraint_violation';\n            END IF;\n\n            IF NEW.attempt_count < OLD.attempt_count THEN\n                RAISE EXCEPTION\n                    'MINDATLAS_PLAN08_CALL_REVISION: attempt_count must be monotonic'\n                    USING ERRCODE = 'integrity_constraint_violation';\n            END IF;\n\n            RETURN NEW;\n        END;\n        $function$")
    op.execute("CREATE OR REPLACE FUNCTION public.mindatlas_capability_reconciliation_append_only()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\n        BEGIN\n            RAISE EXCEPTION\n                'MINDATLAS_PLAN08_RECONCILIATION_APPEND_ONLY: reconciliation rows are append-only'\n                USING ERRCODE = 'integrity_constraint_violation';\n            RETURN NULL;\n        END;\n        $function$")
    op.execute("CREATE OR REPLACE FUNCTION public.mindatlas_checkpoint_same_run_guard()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\n        DECLARE\n            owner uuid;\n        BEGIN\n            SELECT run_id INTO owner FROM assistant_run_manifest_revision\n             WHERE id = NEW.manifest_revision_id;\n            IF owner IS NULL OR owner <> NEW.run_id THEN\n                RAISE EXCEPTION\n                    'MINDATLAS_PLAN06_POINTER_OWNERSHIP: checkpoint manifest revision mismatch'\n                    USING ERRCODE = 'integrity_constraint_violation';\n            END IF;\n            SELECT run_id INTO owner FROM assistant_run_policy_revision\n             WHERE id = NEW.policy_revision_id;\n            IF owner IS NULL OR owner <> NEW.run_id THEN\n                RAISE EXCEPTION\n                    'MINDATLAS_PLAN06_POINTER_OWNERSHIP: checkpoint policy revision mismatch'\n                    USING ERRCODE = 'integrity_constraint_violation';\n            END IF;\n            SELECT run_id INTO owner FROM assistant_run_budget_revision\n             WHERE id = NEW.budget_revision_id;\n            IF owner IS NULL OR owner <> NEW.run_id THEN\n                RAISE EXCEPTION\n                    'MINDATLAS_PLAN06_POINTER_OWNERSHIP: checkpoint budget revision mismatch'\n                    USING ERRCODE = 'integrity_constraint_violation';\n            END IF;\n            SELECT run_id INTO owner FROM assistant_run_obligation_revision\n             WHERE id = NEW.obligation_revision_id;\n            IF owner IS NULL OR owner <> NEW.run_id THEN\n                RAISE EXCEPTION\n                    'MINDATLAS_PLAN06_POINTER_OWNERSHIP: checkpoint obligation revision mismatch'\n                    USING ERRCODE = 'integrity_constraint_violation';\n            END IF;\n            RETURN NEW;\n        END;\n        $function$")
    op.execute("CREATE OR REPLACE FUNCTION public.mindatlas_credential_runtime_revision_guard()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\n        DECLARE\n            exec_changed boolean;\n            rev_delta integer;\n        BEGIN\n            exec_changed := (\n                NEW.base_url IS DISTINCT FROM OLD.base_url\n                OR NEW.api_key_encrypted IS DISTINCT FROM OLD.api_key_encrypted\n            );\n            rev_delta := NEW.runtime_revision - OLD.runtime_revision;\n\n            IF exec_changed AND rev_delta <> 1 THEN\n                RAISE EXCEPTION\n                    'MINDATLAS_PLAN01_REVISION: credential execution change must advance runtime_revision by exactly 1'\n                    USING ERRCODE = 'integrity_constraint_violation';\n            END IF;\n            IF (NOT exec_changed) AND rev_delta <> 0 THEN\n                RAISE EXCEPTION\n                    'MINDATLAS_PLAN01_REVISION: credential runtime_revision-only change is rejected'\n                    USING ERRCODE = 'integrity_constraint_violation';\n            END IF;\n            IF rev_delta < 0 THEN\n                RAISE EXCEPTION\n                    'MINDATLAS_PLAN01_REVISION: runtime_revision cannot decrease'\n                    USING ERRCODE = 'integrity_constraint_violation';\n            END IF;\n            RETURN NEW;\n        END;\n        $function$")
    op.execute("CREATE OR REPLACE FUNCTION public.mindatlas_durable_run_pointer_guard()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\n        DECLARE\n            owner uuid;\n        BEGIN\n            IF NEW.current_manifest_revision_id IS NOT NULL THEN\n                SELECT run_id INTO owner\n                  FROM assistant_run_manifest_revision\n                 WHERE id = NEW.current_manifest_revision_id;\n                IF owner IS NULL THEN\n                    RAISE EXCEPTION\n                        'MINDATLAS_PLAN06_POINTER_OWNERSHIP: current_manifest_revision_id missing'\n                        USING ERRCODE = 'integrity_constraint_violation';\n                END IF;\n                IF owner <> NEW.id THEN\n                    RAISE EXCEPTION\n                        'MINDATLAS_PLAN06_POINTER_OWNERSHIP: manifest revision must belong to run'\n                        USING ERRCODE = 'integrity_constraint_violation';\n                END IF;\n            END IF;\n\n            IF NEW.current_policy_revision_id IS NOT NULL THEN\n                SELECT run_id INTO owner\n                  FROM assistant_run_policy_revision\n                 WHERE id = NEW.current_policy_revision_id;\n                IF owner IS NULL THEN\n                    RAISE EXCEPTION\n                        'MINDATLAS_PLAN06_POINTER_OWNERSHIP: current_policy_revision_id missing'\n                        USING ERRCODE = 'integrity_constraint_violation';\n                END IF;\n                IF owner <> NEW.id THEN\n                    RAISE EXCEPTION\n                        'MINDATLAS_PLAN06_POINTER_OWNERSHIP: policy revision must belong to run'\n                        USING ERRCODE = 'integrity_constraint_violation';\n                END IF;\n            END IF;\n\n            IF NEW.current_budget_revision_id IS NOT NULL THEN\n                SELECT run_id INTO owner\n                  FROM assistant_run_budget_revision\n                 WHERE id = NEW.current_budget_revision_id;\n                IF owner IS NULL THEN\n                    RAISE EXCEPTION\n                        'MINDATLAS_PLAN06_POINTER_OWNERSHIP: current_budget_revision_id missing'\n                        USING ERRCODE = 'integrity_constraint_violation';\n                END IF;\n                IF owner <> NEW.id THEN\n                    RAISE EXCEPTION\n                        'MINDATLAS_PLAN06_POINTER_OWNERSHIP: budget revision must belong to run'\n                        USING ERRCODE = 'integrity_constraint_violation';\n                END IF;\n            END IF;\n\n            IF NEW.current_obligation_revision_id IS NOT NULL THEN\n                SELECT run_id INTO owner\n                  FROM assistant_run_obligation_revision\n                 WHERE id = NEW.current_obligation_revision_id;\n                IF owner IS NULL THEN\n                    RAISE EXCEPTION\n                        'MINDATLAS_PLAN06_POINTER_OWNERSHIP: current_obligation_revision_id missing'\n                        USING ERRCODE = 'integrity_constraint_violation';\n                END IF;\n                IF owner <> NEW.id THEN\n                    RAISE EXCEPTION\n                        'MINDATLAS_PLAN06_POINTER_OWNERSHIP: obligation revision must belong to run'\n                        USING ERRCODE = 'integrity_constraint_violation';\n                END IF;\n            END IF;\n\n            IF NEW.current_checkpoint_id IS NOT NULL THEN\n                SELECT run_id INTO owner\n                  FROM assistant_run_checkpoint\n                 WHERE id = NEW.current_checkpoint_id;\n                IF owner IS NULL THEN\n                    RAISE EXCEPTION\n                        'MINDATLAS_PLAN06_POINTER_OWNERSHIP: current_checkpoint_id missing'\n                        USING ERRCODE = 'integrity_constraint_violation';\n                END IF;\n                IF owner <> NEW.id THEN\n                    RAISE EXCEPTION\n                        'MINDATLAS_PLAN06_POINTER_OWNERSHIP: checkpoint must belong to run'\n                        USING ERRCODE = 'integrity_constraint_violation';\n                END IF;\n            END IF;\n\n            RETURN NEW;\n        END;\n        $function$")
    op.execute("CREATE OR REPLACE FUNCTION public.mindatlas_eval_run_transition_guard()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\n        BEGIN\n            IF NEW.state_revision < OLD.state_revision THEN\n                RAISE EXCEPTION\n                    'MINDATLAS_PLAN09_EVAL_REVISION: state_revision must be monotonic'\n                    USING ERRCODE = 'integrity_constraint_violation';\n            END IF;\n            IF OLD.status IN ('completed','failed','cancelled')\n               AND NEW.status IS DISTINCT FROM OLD.status THEN\n                RAISE EXCEPTION\n                    'MINDATLAS_PLAN09_EVAL_TERMINAL: terminal run status is immutable'\n                    USING ERRCODE = 'integrity_constraint_violation';\n            END IF;\n            IF OLD.status IS DISTINCT FROM NEW.status THEN\n                IF NOT (\n                    (OLD.status = 'queued' AND NEW.status IN ('running','cancelling','cancelled','failed'))\n                    OR (OLD.status = 'running' AND NEW.status IN (\n                        'completed','failed','cancelled','queued','cancelling'\n                    ))\n                    OR (OLD.status = 'cancelling' AND NEW.status = 'cancelled')\n                ) THEN\n                    RAISE EXCEPTION\n                        'MINDATLAS_PLAN09_EVAL_TRANSITION: % -> % not allowed',\n                        OLD.status, NEW.status\n                        USING ERRCODE = 'integrity_constraint_violation';\n                END IF;\n            END IF;\n            IF NEW.owner_kind IS DISTINCT FROM 'test' THEN\n                RAISE EXCEPTION\n                    'MINDATLAS_PLAN09_EVAL_OWNER: owner_kind must remain test'\n                    USING ERRCODE = 'integrity_constraint_violation';\n            END IF;\n            RETURN NEW;\n        END;\n        $function$")
    op.execute("CREATE OR REPLACE FUNCTION public.mindatlas_interrupt_origin_immutable()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\n        BEGIN\n            IF NEW.interrupt_origin IS DISTINCT FROM OLD.interrupt_origin\n               OR NEW.capability_call_id IS DISTINCT FROM OLD.capability_call_id\n            THEN\n                RAISE EXCEPTION\n                    'MINDATLAS_PLAN08_IMMUTABLE_INTERRUPT_ORIGIN: origin/call linkage is immutable'\n                    USING ERRCODE = 'integrity_constraint_violation';\n            END IF;\n            RETURN NEW;\n        END;\n        $function$")
    op.execute("CREATE OR REPLACE FUNCTION public.mindatlas_interrupt_same_run_guard()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\n        DECLARE\n            owner uuid;\n        BEGIN\n            SELECT run_id INTO owner FROM assistant_run_checkpoint\n             WHERE id = NEW.checkpoint_id;\n            IF owner IS NULL OR owner <> NEW.run_id THEN\n                RAISE EXCEPTION\n                    'MINDATLAS_PLAN07_POINTER_OWNERSHIP: interrupt checkpoint mismatch'\n                    USING ERRCODE = 'integrity_constraint_violation';\n            END IF;\n\n            IF NEW.resolution_checkpoint_id IS NOT NULL THEN\n                SELECT run_id INTO owner FROM assistant_run_checkpoint\n                 WHERE id = NEW.resolution_checkpoint_id;\n                IF owner IS NULL OR owner <> NEW.run_id THEN\n                    RAISE EXCEPTION\n                        'MINDATLAS_PLAN07_POINTER_OWNERSHIP: interrupt resolution checkpoint mismatch'\n                        USING ERRCODE = 'integrity_constraint_violation';\n                END IF;\n            END IF;\n\n            SELECT run_id INTO owner FROM assistant_run_manifest_revision\n             WHERE id = NEW.manifest_revision_id;\n            IF owner IS NULL OR owner <> NEW.run_id THEN\n                RAISE EXCEPTION\n                    'MINDATLAS_PLAN07_POINTER_OWNERSHIP: interrupt manifest revision mismatch'\n                    USING ERRCODE = 'integrity_constraint_violation';\n            END IF;\n\n            SELECT run_id INTO owner FROM assistant_run_budget_revision\n             WHERE id = NEW.budget_revision_id;\n            IF owner IS NULL OR owner <> NEW.run_id THEN\n                RAISE EXCEPTION\n                    'MINDATLAS_PLAN07_POINTER_OWNERSHIP: interrupt budget revision mismatch'\n                    USING ERRCODE = 'integrity_constraint_violation';\n            END IF;\n\n            IF NEW.resolution_budget_revision_id IS NOT NULL THEN\n                SELECT run_id INTO owner FROM assistant_run_budget_revision\n                 WHERE id = NEW.resolution_budget_revision_id;\n                IF owner IS NULL OR owner <> NEW.run_id THEN\n                    RAISE EXCEPTION\n                        'MINDATLAS_PLAN07_POINTER_OWNERSHIP: interrupt resolution budget revision mismatch'\n                        USING ERRCODE = 'integrity_constraint_violation';\n                END IF;\n            END IF;\n\n            RETURN NEW;\n        END;\n        $function$")
    op.execute("CREATE OR REPLACE FUNCTION public.mindatlas_main_agent_pointer_guard()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\n        DECLARE\n            draft_profile uuid;\n            draft_src text;\n            pub_profile uuid;\n            pub_src text;\n        BEGIN\n            IF NEW.draft_version_id IS NOT NULL THEN\n                SELECT profile_id, version_source\n                  INTO draft_profile, draft_src\n                  FROM assistant_main_agent_profile_version\n                 WHERE id = NEW.draft_version_id;\n                IF draft_profile IS NULL OR draft_profile <> NEW.id THEN\n                    RAISE EXCEPTION\n                        'MINDATLAS_PLAN01_POINTER_OWNERSHIP: draft_version_id must belong to profile'\n                        USING ERRCODE = 'integrity_constraint_violation';\n                END IF;\n                IF draft_src <> 'save' THEN\n                    RAISE EXCEPTION\n                        'MINDATLAS_PLAN01_POINTER_SOURCE: draft_version_id must reference save'\n                        USING ERRCODE = 'integrity_constraint_violation';\n                END IF;\n            END IF;\n\n            IF NEW.published_version_id IS NOT NULL THEN\n                SELECT profile_id, version_source\n                  INTO pub_profile, pub_src\n                  FROM assistant_main_agent_profile_version\n                 WHERE id = NEW.published_version_id;\n                IF pub_profile IS NULL OR pub_profile <> NEW.id THEN\n                    RAISE EXCEPTION\n                        'MINDATLAS_PLAN01_POINTER_OWNERSHIP: published_version_id must belong to profile'\n                        USING ERRCODE = 'integrity_constraint_violation';\n                END IF;\n                IF pub_src <> 'publish' THEN\n                    RAISE EXCEPTION\n                        'MINDATLAS_PLAN01_POINTER_SOURCE: published_version_id must reference publish'\n                        USING ERRCODE = 'integrity_constraint_violation';\n                END IF;\n            END IF;\n            RETURN NEW;\n        END;\n        $function$")
    op.execute("CREATE OR REPLACE FUNCTION public.mindatlas_main_agent_source_draft_guard()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\n        DECLARE\n            src_profile uuid;\n            src_src text;\n        BEGIN\n            IF NEW.version_source = 'publish' THEN\n                IF NEW.source_draft_version_id IS NULL THEN\n                    RAISE EXCEPTION\n                        'MINDATLAS_PLAN01_SOURCE_DRAFT: publish requires source_draft_version_id'\n                        USING ERRCODE = 'integrity_constraint_violation';\n                END IF;\n                SELECT profile_id, version_source\n                  INTO src_profile, src_src\n                  FROM assistant_main_agent_profile_version\n                 WHERE id = NEW.source_draft_version_id;\n                IF src_profile IS NULL OR src_profile <> NEW.profile_id THEN\n                    RAISE EXCEPTION\n                        'MINDATLAS_PLAN01_SOURCE_DRAFT: source_draft_version_id must belong to profile'\n                        USING ERRCODE = 'integrity_constraint_violation';\n                END IF;\n                IF src_src <> 'save' THEN\n                    RAISE EXCEPTION\n                        'MINDATLAS_PLAN01_SOURCE_DRAFT: source_draft_version_id must name save'\n                        USING ERRCODE = 'integrity_constraint_violation';\n                END IF;\n            END IF;\n            RETURN NEW;\n        END;\n        $function$")
    op.execute("CREATE OR REPLACE FUNCTION public.mindatlas_model_runtime_revision_guard()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\n        DECLARE\n            exec_changed boolean;\n            rev_delta integer;\n        BEGIN\n            exec_changed := (\n                NEW.name IS DISTINCT FROM OLD.name\n                OR NEW.model_type IS DISTINCT FROM OLD.model_type\n                OR NEW.credential_id IS DISTINCT FROM OLD.credential_id\n            );\n            rev_delta := NEW.runtime_revision - OLD.runtime_revision;\n\n            IF exec_changed AND rev_delta <> 1 THEN\n                RAISE EXCEPTION\n                    'MINDATLAS_PLAN01_REVISION: model execution change must advance runtime_revision by exactly 1'\n                    USING ERRCODE = 'integrity_constraint_violation';\n            END IF;\n            IF (NOT exec_changed) AND rev_delta <> 0 THEN\n                RAISE EXCEPTION\n                    'MINDATLAS_PLAN01_REVISION: model runtime_revision-only change is rejected'\n                    USING ERRCODE = 'integrity_constraint_violation';\n            END IF;\n            IF rev_delta < 0 THEN\n                RAISE EXCEPTION\n                    'MINDATLAS_PLAN01_REVISION: runtime_revision cannot decrease'\n                    USING ERRCODE = 'integrity_constraint_violation';\n            END IF;\n            RETURN NEW;\n        END;\n        $function$")
    op.execute("CREATE OR REPLACE FUNCTION public.mindatlas_provider_message_same_run_guard()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\n        DECLARE\n            owner uuid;\n        BEGIN\n            SELECT run_id INTO owner\n              FROM assistant_run_manifest_revision\n             WHERE id = NEW.manifest_revision_id;\n            IF owner IS NULL OR owner <> NEW.run_id THEN\n                RAISE EXCEPTION\n                    'MINDATLAS_PLAN06_POINTER_OWNERSHIP: provider message manifest revision mismatch'\n                    USING ERRCODE = 'integrity_constraint_violation';\n            END IF;\n\n            IF NEW.policy_revision_id IS NOT NULL THEN\n                SELECT run_id INTO owner\n                  FROM assistant_run_policy_revision\n                 WHERE id = NEW.policy_revision_id;\n                IF owner IS NULL OR owner <> NEW.run_id THEN\n                    RAISE EXCEPTION\n                        'MINDATLAS_PLAN06_POINTER_OWNERSHIP: provider message policy revision mismatch'\n                        USING ERRCODE = 'integrity_constraint_violation';\n                END IF;\n            END IF;\n\n            IF NEW.obligation_revision_id IS NOT NULL THEN\n                SELECT run_id INTO owner\n                  FROM assistant_run_obligation_revision\n                 WHERE id = NEW.obligation_revision_id;\n                IF owner IS NULL OR owner <> NEW.run_id THEN\n                    RAISE EXCEPTION\n                        'MINDATLAS_PLAN06_POINTER_OWNERSHIP: provider message obligation revision mismatch'\n                        USING ERRCODE = 'integrity_constraint_violation';\n                END IF;\n            END IF;\n\n            RETURN NEW;\n        END;\n        $function$")
    op.execute("CREATE OR REPLACE FUNCTION public.mindatlas_reconciliation_evidence_immutable()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n    IF EXISTS (\n        SELECT 1\n        FROM assistant_capability_reconciliation AS reconciliation\n        WHERE reconciliation.run_id = OLD.run_id\n          AND COALESCE(\n                reconciliation.evidence_artifact_ids::jsonb,\n                '[]'::jsonb\n              ) @> jsonb_build_array(OLD.id::text)\n    ) THEN\n        RAISE EXCEPTION\n            'MINDATLAS_PLAN08_RECONCILIATION_EVIDENCE_IMMUTABLE: referenced evidence cannot be changed'\n            USING ERRCODE = 'integrity_constraint_violation';\n    END IF;\n    IF TG_OP = 'DELETE' THEN\n        RETURN OLD;\n    END IF;\n    RETURN NEW;\nEND;\n$function$")
    op.execute("CREATE OR REPLACE FUNCTION public.mindatlas_reject_bootstrap_gate_use_mutation()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n  RAISE EXCEPTION 'assistant runtime bootstrap gate use is immutable'\n    USING ERRCODE = 'integrity_constraint_violation';\nEND;\n$function$")
    op.execute("CREATE OR REPLACE FUNCTION public.mindatlas_reject_durable_run_mutation()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\n        DECLARE\n            allow_purge text;\n        BEGIN\n            IF TG_OP = 'UPDATE' THEN\n                RAISE EXCEPTION\n                    'MINDATLAS_PLAN06_IMMUTABLE_ROW: UPDATE on % is not allowed',\n                    TG_TABLE_NAME\n                    USING ERRCODE = 'integrity_constraint_violation';\n            END IF;\n            -- DELETE allowed only when local purge flag is set (conversation delete).\n            allow_purge := current_setting('mindatlas.allow_durable_run_purge', true);\n            IF allow_purge IS DISTINCT FROM 'on' THEN\n                RAISE EXCEPTION\n                    'MINDATLAS_PLAN06_IMMUTABLE_ROW: DELETE on % requires '\n                    'SET LOCAL mindatlas.allow_durable_run_purge = ''on''',\n                    TG_TABLE_NAME\n                    USING ERRCODE = 'integrity_constraint_violation';\n            END IF;\n            RETURN OLD;\n        END;\n        $function$")
    op.execute("CREATE OR REPLACE FUNCTION public.mindatlas_reject_eval_immutable_mutation()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\n        BEGIN\n            RAISE EXCEPTION\n                'MINDATLAS_PLAN09_EVAL_IMMUTABLE: % on % is not allowed',\n                TG_OP, TG_TABLE_NAME\n                USING ERRCODE = 'integrity_constraint_violation';\n        END;\n        $function$")
    op.execute("CREATE OR REPLACE FUNCTION public.mindatlas_reject_immutable_mutation()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\n        BEGIN\n            RAISE EXCEPTION\n                'MINDATLAS_PLAN01_IMMUTABLE_ROW: % on % is not allowed',\n                TG_OP, TG_TABLE_NAME\n                USING ERRCODE = 'integrity_constraint_violation';\n        END;\n        $function$")
    op.execute("CREATE OR REPLACE FUNCTION public.mindatlas_reject_operator_audit_mutation()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n  RAISE EXCEPTION 'operator_audit_event is append-only'\n    USING ERRCODE = '55000';\nEND;\n$function$")
    op.execute("CREATE OR REPLACE FUNCTION public.mindatlas_reject_rollout_revision_mutation()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n  RAISE EXCEPTION 'assistant rollout revision is immutable'\n    USING ERRCODE = 'integrity_constraint_violation';\nEND;\n$function$")
    op.execute("CREATE OR REPLACE FUNCTION public.mindatlas_reject_run_runtime_identity_mutation()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n  IF NEW.runtime_kind IS DISTINCT FROM OLD.runtime_kind\n     OR NEW.main_agent_rollout_revision_id IS DISTINCT FROM OLD.main_agent_rollout_revision_id\n     OR NEW.main_agent_profile_version_id IS DISTINCT FROM OLD.main_agent_profile_version_id\n     OR NEW.resolved_model_id IS DISTINCT FROM OLD.resolved_model_id\n     OR NEW.runtime_closure_digest IS DISTINCT FROM OLD.runtime_closure_digest\n     OR NEW.runtime_contract_version IS DISTINCT FROM OLD.runtime_contract_version\n     OR NEW.required_checkpoint_codec_version IS DISTINCT FROM OLD.required_checkpoint_codec_version\n     OR NEW.required_capability_feature_digest IS DISTINCT FROM OLD.required_capability_feature_digest\n     OR NEW.required_app_build_revision IS DISTINCT FROM OLD.required_app_build_revision\n     OR NEW.capability_ledger_mode IS DISTINCT FROM OLD.capability_ledger_mode\n  THEN\n    RAISE EXCEPTION 'assistant Run runtime identity is immutable'\n      USING ERRCODE = 'integrity_constraint_violation';\n  END IF;\n  RETURN NEW;\nEND;\n$function$")
    op.execute("CREATE OR REPLACE FUNCTION public.mindatlas_skill_package_alias_soft_disable_guard()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\n        BEGIN\n            -- Identity / naming columns remain immutable.\n            IF NEW.id IS DISTINCT FROM OLD.id\n               OR NEW.skill_package_id IS DISTINCT FROM OLD.skill_package_id\n               OR NEW.alias IS DISTINCT FROM OLD.alias\n               OR NEW.normalized_alias IS DISTINCT FROM OLD.normalized_alias\n               OR NEW.alias_type IS DISTINCT FROM OLD.alias_type\n               OR NEW.created_at IS DISTINCT FROM OLD.created_at\n            THEN\n                RAISE EXCEPTION\n                    'MINDATLAS_PLAN01_IMMUTABLE_ROW: UPDATE on % identity/name columns is not allowed',\n                    TG_TABLE_NAME\n                    USING ERRCODE = 'integrity_constraint_violation';\n            END IF;\n            -- Only disabled_at / disabled_by (soft-disable) may change.\n            RETURN NEW;\n        END;\n        $function$")
    op.execute("CREATE OR REPLACE FUNCTION public.mindatlas_skill_package_pointer_guard()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\n        DECLARE\n            draft_pkg uuid;\n            draft_src text;\n            pub_pkg uuid;\n            pub_src text;\n        BEGIN\n            IF NEW.draft_version_id IS NOT NULL THEN\n                SELECT skill_package_id, version_source\n                  INTO draft_pkg, draft_src\n                  FROM assistant_skill_version\n                 WHERE id = NEW.draft_version_id;\n                IF draft_pkg IS NULL THEN\n                    RAISE EXCEPTION\n                        'MINDATLAS_PLAN01_POINTER_OWNERSHIP: draft_version_id missing'\n                        USING ERRCODE = 'integrity_constraint_violation';\n                END IF;\n                IF draft_pkg <> NEW.id THEN\n                    RAISE EXCEPTION\n                        'MINDATLAS_PLAN01_POINTER_OWNERSHIP: draft_version_id must belong to package'\n                        USING ERRCODE = 'integrity_constraint_violation';\n                END IF;\n                IF draft_src <> 'save' THEN\n                    RAISE EXCEPTION\n                        'MINDATLAS_PLAN01_POINTER_SOURCE: draft_version_id must reference save'\n                        USING ERRCODE = 'integrity_constraint_violation';\n                END IF;\n            END IF;\n\n            IF NEW.published_version_id IS NOT NULL THEN\n                SELECT skill_package_id, version_source\n                  INTO pub_pkg, pub_src\n                  FROM assistant_skill_version\n                 WHERE id = NEW.published_version_id;\n                IF pub_pkg IS NULL THEN\n                    RAISE EXCEPTION\n                        'MINDATLAS_PLAN01_POINTER_OWNERSHIP: published_version_id missing'\n                        USING ERRCODE = 'integrity_constraint_violation';\n                END IF;\n                IF pub_pkg <> NEW.id THEN\n                    RAISE EXCEPTION\n                        'MINDATLAS_PLAN01_POINTER_OWNERSHIP: published_version_id must belong to package'\n                        USING ERRCODE = 'integrity_constraint_violation';\n                END IF;\n                IF pub_src <> 'publish' THEN\n                    RAISE EXCEPTION\n                        'MINDATLAS_PLAN01_POINTER_SOURCE: published_version_id must reference publish'\n                        USING ERRCODE = 'integrity_constraint_violation';\n                END IF;\n            END IF;\n            RETURN NEW;\n        END;\n        $function$")
    op.execute("CREATE OR REPLACE FUNCTION public.mindatlas_skill_resource_blob_guard()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\n        DECLARE\n            blob_sha text;\n            blob_size integer;\n            orphan_count integer;\n            mismatch_count integer;\n        BEGIN\n            SELECT COUNT(*) INTO mismatch_count\n              FROM assistant_skill_version_resource r\n              JOIN assistant_skill_resource_blob b ON b.id = r.blob_id\n             WHERE r.sha256 <> b.sha256 OR r.byte_size <> b.byte_size;\n            IF mismatch_count > 0 THEN\n                RAISE EXCEPTION\n                    'MINDATLAS_PLAN01_BLOB_METADATA: version resource sha256/byte_size must equal blob'\n                    USING ERRCODE = 'integrity_constraint_violation';\n            END IF;\n\n            SELECT COUNT(*) INTO orphan_count\n              FROM assistant_skill_resource_blob b\n             WHERE NOT EXISTS (\n                SELECT 1 FROM assistant_skill_version_resource r WHERE r.blob_id = b.id\n             );\n            IF orphan_count > 0 THEN\n                RAISE EXCEPTION\n                    'MINDATLAS_PLAN01_BLOB_ORPHAN: every blob must be referenced by a version resource'\n                    USING ERRCODE = 'integrity_constraint_violation';\n            END IF;\n            RETURN NULL;\n        END;\n        $function$")
    op.execute("CREATE OR REPLACE FUNCTION public.mindatlas_skill_version_source_draft_guard()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\n        DECLARE\n            src_pkg uuid;\n            src_src text;\n        BEGIN\n            IF NEW.version_source = 'publish' THEN\n                IF NEW.source_draft_version_id IS NULL THEN\n                    RAISE EXCEPTION\n                        'MINDATLAS_PLAN01_SOURCE_DRAFT: publish requires source_draft_version_id'\n                        USING ERRCODE = 'integrity_constraint_violation';\n                END IF;\n                SELECT skill_package_id, version_source\n                  INTO src_pkg, src_src\n                  FROM assistant_skill_version\n                 WHERE id = NEW.source_draft_version_id;\n                IF src_pkg IS NULL OR src_pkg <> NEW.skill_package_id THEN\n                    RAISE EXCEPTION\n                        'MINDATLAS_PLAN01_SOURCE_DRAFT: source_draft_version_id must belong to package'\n                        USING ERRCODE = 'integrity_constraint_violation';\n                END IF;\n                IF src_src <> 'save' THEN\n                    RAISE EXCEPTION\n                        'MINDATLAS_PLAN01_SOURCE_DRAFT: source_draft_version_id must name save'\n                        USING ERRCODE = 'integrity_constraint_violation';\n                END IF;\n            END IF;\n            RETURN NEW;\n        END;\n        $function$")
    op.execute("CREATE OR REPLACE FUNCTION public.mindatlas_tool_config_revision_guard()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\n        DECLARE\n            exec_changed boolean;\n            rev_delta integer;\n        BEGIN\n            exec_changed := (\n                NEW.name IS DISTINCT FROM OLD.name\n                OR NEW.kind IS DISTINCT FROM OLD.kind\n                OR NEW.endpoint_url IS DISTINCT FROM OLD.endpoint_url\n                OR NEW.http_method IS DISTINCT FROM OLD.http_method\n                OR (NEW.headers::jsonb) IS DISTINCT FROM (OLD.headers::jsonb)\n                OR (NEW.query_params::jsonb) IS DISTINCT FROM (OLD.query_params::jsonb)\n                OR NEW.body_type IS DISTINCT FROM OLD.body_type\n                OR NEW.body_content IS DISTINCT FROM OLD.body_content\n                OR NEW.auth_type IS DISTINCT FROM OLD.auth_type\n                OR NEW.auth_header_name IS DISTINCT FROM OLD.auth_header_name\n                OR NEW.auth_scheme IS DISTINCT FROM OLD.auth_scheme\n                OR NEW.api_key_encrypted IS DISTINCT FROM OLD.api_key_encrypted\n                OR NEW.timeout_seconds IS DISTINCT FROM OLD.timeout_seconds\n                OR NEW.payload_wrapper IS DISTINCT FROM OLD.payload_wrapper\n                OR (NEW.input_params::jsonb) IS DISTINCT FROM (OLD.input_params::jsonb)\n            );\n            rev_delta := NEW.config_revision - OLD.config_revision;\n\n            IF exec_changed AND rev_delta <> 1 THEN\n                RAISE EXCEPTION\n                    'MINDATLAS_PLAN01_REVISION: tool execution change must advance config_revision by exactly 1'\n                    USING ERRCODE = 'integrity_constraint_violation';\n            END IF;\n            IF (NOT exec_changed) AND rev_delta <> 0 THEN\n                RAISE EXCEPTION\n                    'MINDATLAS_PLAN01_REVISION: tool config_revision-only change is rejected'\n                    USING ERRCODE = 'integrity_constraint_violation';\n            END IF;\n            IF rev_delta < 0 THEN\n                RAISE EXCEPTION\n                    'MINDATLAS_PLAN01_REVISION: config_revision cannot decrease'\n                    USING ERRCODE = 'integrity_constraint_violation';\n            END IF;\n            RETURN NEW;\n        END;\n        $function$")
